(3491218, 487571, 30982, '<td valign="top">Excellent.  Very much like the toning and the crossed lines of the bass and the mic stand.  Very nice indeed.</td>', 'Excellent.  Very much like the toning and the crossed lines of the bass and the mic stand.  Very nice indeed.', '2007-03-27 15:09:02.000000', NULL, 1),
(3491219, 488071, 30982, '<td valign="top">My kinda shot.  I love the simplicity of this.  Just don''t tell me you''re saying "Stop" to Starbucks... gotta have it.  Love the textures, the view inside.  Nicely captured and presented.</td>', 'My kinda shot.  I love the simplicity of this.  Just don''t tell me you''re saying "Stop" to Starbucks... gotta have it.  Love the textures, the view inside.  Nicely captured and presented.', '2007-03-27 15:09:46.000000', NULL, 1),
(3491220, 487818, 30982, '<td valign="top">You''ll probably get grief for not cleaning the toaster.  :-)  Love the duality of "burning toasters" along with the "Pop Culture" of, umm, borrowing music.  Nicely done.</td>', 'You''ll probably get grief for not cleaning the toaster.  :-)  Love the duality of "burning toasters" along with the "Pop Culture" of, umm, borrowing music.  Nicely done.', '2007-03-27 15:10:33.000000', NULL, 1),
(3491223, 488141, 30982, '<td valign="top">Good idea for this challenge.  I might have liked just a wee bit more light to show the labels, but I love the orange glow behind and the way it makes the bottom of the bottles look.</td>', 'Good idea for this challenge.  I might have liked just a wee bit more light to show the labels, but I love the orange glow behind and the way it makes the bottom of the bottles look.', '2007-03-27 15:11:30.000000', NULL, 1),
(3491225, 487701, 30982, '<td valign="top">Great background for this shot!  The processing emphasizes the "pop" aspect well.</td>', 'Great background for this shot!  The processing emphasizes the "pop" aspect well.', '2007-03-27 15:11:56.000000', NULL, 1),
(3491226, 488403, 30982, '<td valign="top">Beautiful.  Simply beautiful.</td>', 'Beautiful.  Simply beautiful.', '2007-03-27 15:12:11.000000', NULL, 1),
(3491230, 488437, 30982, '<td valign="top">Excellent choice!  Love the location, love the angle/perspective, love the color.  The eyes definitely make the shot.</td>', 'Excellent choice!  Love the location, love the angle/perspective, love the color.  The eyes definitely make the shot.', '2007-03-27 15:12:54.000000', NULL, 1),
