(3495859, 488403, 42098, '<td valign="top">A nice blend of satin and shine, really caught my eye.</td>', 'A nice blend of satin and shine, really caught my eye.', '2007-03-29 00:50:25.000000', NULL, 1),
(3495904, 488402, 1031, '<td valign="top">Shoes with high heels can be OK, and shoes with pointy toes can be OK, but shoes with both are a kinesiological abomination -- in the long run it''s not comfort but health which is at risk.</td>', 'Shoes with high heels can be OK, and shoes with pointy toes can be OK, but shoes with both are a kinesiological abomination -- in the long run it''s not comfort but health which is at risk.', '2007-03-29 01:29:04.000000', NULL, 1),
