(3496132, 488399, 49930, '<td valign="top">I''m not sure what this has to do with Pop culture but I love this shot. Great subject , effective B&amp;W, great framing - I like the way the hand goes out of the frame with the second head in the background. 10</td>', 'I''m not sure what this has to do with Pop culture but I love this shot. Great subject , effective B&W, great framing - I like the way the hand goes out of the frame with the second head in the background. 10', '2007-03-29 04:28:15.000000', NULL, 1),
(3496133, 488233, 49930, '<td valign="top">Effective colour, simple frame (by that I mean uncluttered - your eye is drawn into the shot). Well done.</td>', 'Effective colour, simple frame (by that I mean uncluttered - your eye is drawn into the shot). Well done.', '2007-03-29 04:30:08.000000', NULL, 1),
(3496136, 488457, 49930, '<td valign="top">Nailed it  (excuse the pun)!! Fits the theme (pop culture. Great framing , great colour range. The one, sharp eye. I think this is the best of the batch. Spot on !! A 10</td>', 'Nailed it  (excuse the pun)!! Fits the theme (pop culture. Great framing , great colour range. The one, sharp eye. I think this is the best of the batch. Spot on !! A 10', '2007-03-29 04:34:04.000000', NULL, 1),
