INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3496930, 487694, 61651, '<td valign="top">Definitely has a sinister feel; nice composition.  Like the way the lighting emphasizes the figure''s unreality.</td>', 'Definitely has a sinister feel; nice composition.  Like the way the lighting emphasizes the figure''s unreality.', '2007-03-29 14:23:42.000000', NULL, 1),
(3496934, 488266, 61651, '<td valign="top">Nicely illustrates the "overload" effect, meets the challenge well.</td>', 'Nicely illustrates the "overload" effect, meets the challenge well.', '2007-03-29 14:24:33.000000', NULL, 1),
(3496938, 488437, 61651, '<td valign="top">Great capture with the eyes on the billboard seemingly following the passing police car.  Great illustration of the pervasiveness of pop culture.</td>', 'Great capture with the eyes on the billboard seemingly following the passing police car.  Great illustration of the pervasiveness of pop culture.', '2007-03-29 14:26:53.000000', NULL, 1),
(3496942, 488079, 61651, '<td valign="top">This is really an interesting concept and nicely shot.  I find the neon green background a bit blinding, though.</td>', 'This is really an interesting concept and nicely shot.  I find the neon green background a bit blinding, though.', '2007-03-29 14:29:05.000000', NULL, 1),
(3496953, 488462, 61651, '<td valign="top">Wow, those pants are tight!  Like the way the torso disappears because the black tank blends in with the backdrop - it seems to emphasize the subject all the more.</td>', 'Wow, those pants are tight!  Like the way the torso disappears because the black tank blends in with the backdrop - it seems to emphasize the subject all the more.', '2007-03-29 14:32:43.000000', NULL, 1),
(3496965, 487618, 61651, '<td valign="top">I won''t penalize you for the fact that the moment I saw your image, I got a "greatest 70''s hits" track on loop running through my head. :)  Nice lighting brings out the sheen of the shoe fabric, would have liked to see less shadow in the top of the image.</td>', 'I won''t penalize you for the fact that the moment I saw your image, I got a "greatest 70''s hits" track on loop running through my head. :)  Nice lighting brings out the sheen of the shoe fabric, would have liked to see less shadow in the top of the image.', '2007-03-29 14:36:54.000000', NULL, 1),
(3496972, 488442, 61651, '<td valign="top">Great example of our pop culture.  I think the composition may have been made more effective with a wider, landscape orientation.</td>', 'Great example of our pop culture.  I think the composition may have been made more effective with a wider, landscape orientation.', '2007-03-29 14:40:02.000000', NULL, 1),
(3496981, 487489, 61651, '<td valign="top">The title gives me a clue to which aspect of pop culture you wanted to highlight, but without the title I would have had a hard time connecting your subject to Pop Culture.  The model is nicely posed, though, it''s a good image.</td>', 'The title gives me a clue to which aspect of pop culture you wanted to highlight, but without the title I would have had a hard time connecting your subject to Pop Culture.  The model is nicely posed, though, it''s a good image.', '2007-03-29 14:42:54.000000', NULL, 1),
(3496985, 487694, 76153, '<td valign="top">I really like this photograph; it gives him a sinister feel, not being able to see his face.</td>', 'I really like this photograph; it gives him a sinister feel, not being able to see his face.', '2007-03-29 14:43:43.000000', NULL, 1),
(3496989, 487820, 76153, '<td valign="top">not an original idea.</td>', 'not an original idea.', '2007-03-29 14:44:32.000000', NULL, 1),
